class Foo { f() { return 'original'; } }
const foo = new Foo();

// Simulate what spyOn does:
let objDescriptor = Object.getOwnPropertyDescriptor(foo, 'f');
let proto = Object.getPrototypeOf(foo);
let protoDescriptor = proto && Object.getOwnPropertyDescriptor(proto, 'f');
let originalDescriptor = objDescriptor || protoDescriptor;
let original = originalDescriptor?.value;

console.log('objDescriptor:', objDescriptor);
console.log('protoDescriptor:', protoDescriptor ? 'found' : 'not found');
console.log('original:', original?.name);

// When reassign is called with original during restore:
let { value, ...desc } = originalDescriptor;
console.log('desc after destructure:', desc);
desc.value = original;
console.log('desc before define:', desc);

// This is what reassign does - creates an own property!
Object.defineProperty(foo, 'f', desc);
console.log('After restore, own descriptor:', Object.getOwnPropertyDescriptor(foo, 'f'));
console.log('Expected: undefined (no own property)');
"
